import React, { useState } from "react";
import { DndProvider, useDrag, useDrop } from "react-dnd";
import { HTML5Backend } from "react-dnd-html5-backend";
import { PlusCircle, CheckCircle, Circle, Trash2 } from "lucide-react";
import "./App.css";

function App() {
  const [tasks, setTasks] = useState([]);
  const [taskInputs, setTaskInputs] = useState({ 1: "", 2: "", 3: "", 4: "" });

  const addTask = (quadrant) => {
    if (!taskInputs[quadrant].trim()) return;
    setTasks([...tasks, { id: Date.now(), text: taskInputs[quadrant], quadrant }]);
    setTaskInputs({ ...taskInputs, [quadrant]: "" });
  };

  const moveTask = (taskId, newQuadrant) => {
    setTasks(tasks.map((task) => (task.id === taskId ? { ...task, quadrant: newQuadrant } : task)));
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="App">
        {/* Matrix Headers */}
        <div className="matrix-container">
          <div className="matrix-header important-header">Important</div>
          <div className="matrix-header not-important-header">Not Important</div>
          <div className="matrix-header urgent-header">Urgent</div>
          <div className="matrix-header not-urgent-header">Not Urgent</div>

          {/* Quadrants */}
          <Quadrant quadrant={1} tasks={tasks} addTask={addTask} moveTask={moveTask} taskInputs={taskInputs} setTaskInputs={setTaskInputs} />
          <Quadrant quadrant={2} tasks={tasks} addTask={addTask} moveTask={moveTask} taskInputs={taskInputs} setTaskInputs={setTaskInputs} />
          <Quadrant quadrant={3} tasks={tasks} addTask={addTask} moveTask={moveTask} taskInputs={taskInputs} setTaskInputs={setTaskInputs} />
          <Quadrant quadrant={4} tasks={tasks} addTask={addTask} moveTask={moveTask} taskInputs={taskInputs} setTaskInputs={setTaskInputs} />
        </div>
      </div>
    </DndProvider>
  );
}

function Quadrant({ quadrant, tasks, addTask, moveTask, taskInputs, setTaskInputs }) {
  const [{ isOver }, drop] = useDrop(() => ({
    accept: "TASK",
    drop: (item) => moveTask(item.id, quadrant),
    collect: (monitor) => ({ isOver: !!monitor.isOver() }),
  }));

  return (
    <div ref={drop} className={`quadrant ${isOver ? "highlight" : ""}`}>
      <div className="task-input">
        <input type="text" placeholder="Enter Task" value={taskInputs[quadrant]} onChange={(e) => setTaskInputs({ ...taskInputs, [quadrant]: e.target.value })} onKeyDown={(e) => e.key === "Enter" && addTask(quadrant)} />
        <PlusCircle className="add-icon" onClick={() => addTask(quadrant)} />
      </div>
      <TaskList quadrant={quadrant} tasks={tasks} />
    </div>
  );
}

function TaskList({ quadrant, tasks }) {
  return (
    <div className="task-list">
      {tasks.filter((task) => task.quadrant === quadrant).map((task) => (
        <Task key={task.id} task={task} />
      ))}
    </div>
  );
}

function Task({ task }) {
  const [{ isDragging }, drag] = useDrag(() => ({
    type: "TASK",
    item: { id: task.id },
    collect: (monitor) => ({ isDragging: !!monitor.isDragging() }),
  }));

  return (
    <div ref={drag} className={`task ${isDragging ? "dragging" : ""}`}>
      <span className="task-checkbox">{task.completed ? <CheckCircle size={16} /> : <Circle size={16} />}</span>
      <span className="task-text">{task.text}</span>
      <span className="task-delete-icon">
        <Trash2 size={16} />
      </span>
    </div>
  );
}

export default App;
